// This week vs last week, one small row per product, with its source.
const rows = $input.all().map(i => i.json).filter(r => r.name && r.price !== '' && r.price_last_week !== '');
const items = rows.map(r => ({
  product: r.name,
  price_now: Number(r.price),
  price_last_week: Number(r.price_last_week),
  source: `Agro Depot price list, ${String(r.fetched_at || '').slice(0, 10)}`,
}));
return [{ json: { found: items.length > 0, items } }];
